content.text:
{
  "name": "Kvaser CAN总线接口适配器",
  "name_en": "Kvaser CAN Bus Interface",
  "manufacturer": "Kvaser",
  "description": "这是一种用于将计算机连接到CAN总线网络的硬件接口设备，可用于发送和接收CAN报文、监测总线通信，以及在实验室中对基于CAN的控制器、仪器或嵌入式设备进行联调、测试与诊断。",
  "description_en": "This is a hardware interface device that connects a computer to a CAN bus network. It is used to transmit and receive CAN messages, monitor bus traffic, and support laboratory integration, testing, and diagnostics of CAN-based controllers, instruments, and embedded systems.",
  "actions": [
    {
      "action_name": "auto-flush_tx_buffer",
      "description": "清空设备的发送缓冲区。",
      "description_en": "Clear the device transmit buffer."
    },
    {
      "action_name": "auto-send",
      "description": "通过CAN总线发送一条报文。",
      "description_en": "Send a message on the CAN bus."
    },
    {
      "action_name": "auto-flash",
      "description": "开启或关闭设备指示灯闪烁，用于物理定位设备。",
      "description_en": "Turn the device LED flashing on or off for physical identification."
    },
    {
      "action_name": "auto-shutdown",
      "description": "安全关闭CAN接口，并等待排队发送的数据处理完成。",
      "description_en": "Safely shut down the CAN interface and wait for queued transmissions to complete."
    }
  ],
  "tag_hints": [
    "CAN bus communication",
    "Kvaser interface",
    "vehicle network testing",
    "CAN message transmission",
    "bus monitoring",
    "ECU diagnostics"
  ]
}

